const texto = $input.first().json.data;

const linhas = texto.trim().split(/\r?\n/);
const cabecalhos = linhas[0].split(',');

const resultado = linhas.slice(1).map((linha, indice) => {
  const valores = linha.split(',');
  const item = {};

  cabecalhos.forEach((coluna, i) => {
    item[coluna] = valores[i];
  });

  return {
    json: {
      numero: indice + 1,
      perfil: item.perfil,
      produto: item.produto,
      minimo: Number(item.minimo),
      rentabilidade: item.rentabilidade
    }
  };
});

return resultado;

const entradas = $input.all();

const clientes = [];
const investimentos = [];

function procurarDados(obj) {
  if (Array.isArray(obj)) {
    for (const item of obj) {
      procurarDados(item);
    }
    return;
  }

  if (!obj || typeof obj !== "object") {
    return;
  }

  // Identifica um cliente
  if (
    obj.nome &&
    obj.email &&
    obj.saldo !== undefined &&
    obj.perfil
  ) {
    clientes.push(obj);
  }

  // Identifica um investimento do CSV
  if (
    obj.produto &&
    obj.perfil &&
    obj.minimo !== undefined
  ) {
    investimentos.push(obj);
  }

  // Procura dentro dos objetos e listas
  for (const valor of Object.values(obj)) {
    if (valor && typeof valor === "object") {
      procurarDados(valor);
    }
  }
}

for (const item of entradas) {
  procurarDados(item.json);
}

// Evita processar o mesmo cliente ou produto duas vezes
const clientesUnicos = [
  ...new Map(
    clientes.map(c => [c.email, c])
  ).values()
];

const investimentosUnicos = [
  ...new Map(
    investimentos.map(i => [
      `${i.perfil}|${i.produto}`,
      i
    ])
  ).values()
];

function converterSaldo(valor) {
  return Number(
    String(valor)
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  );
}

const saida = clientesUnicos.map(cliente => {
  const saldo = converterSaldo(cliente.saldo);

  const recomendados = investimentosUnicos.filter(inv =>
    String(inv.perfil).trim().toLowerCase() ===
      String(cliente.perfil).trim().toLowerCase() &&
    saldo >= converterSaldo(inv.minimo)
  );

  const lista = recomendados.length
    ? recomendados.map(inv =>
        `- ${inv.produto} | Mínimo: R$ ${Number(inv.minimo).toLocaleString("pt-BR")} | Rentabilidade informada: ${inv.rentabilidade}`
      ).join("\n")
    : "Nenhum produto elegível encontrado nos dados recebidos.";

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      mensagem:
`Olá, ${cliente.nome}!

Seu perfil de investimento é ${cliente.perfil} e seu saldo informado é ${cliente.saldo}.

Opções para avaliar:
${lista}

As opções acima são informativas e não constituem recomendação financeira personalizada. Rentabilidades não são garantidas.`
    }
  };
});

// Se não encontrou clientes, retorna um diagnóstico em vez de zero itens
if (saida.length === 0) {
  return [{
    json: {
      erro: "Nenhum cliente foi identificado.",
      itensRecebidos: entradas.length,
      chavesDoPrimeiroItem: Object.keys(entradas[0]?.json ?? {}),
      exemploRecebido: entradas[0]?.json ?? null
    }
  }];
}

return saida;

const dados = $input.all();

const tabela = dados.map((item, index) => {
  const cliente = item.json;

  return {
    numero: index + 1,
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo: cliente.saldo,
    mensagem: cliente.mensagem
  };
});

return tabela.map(cliente => ({
  json: cliente
}));

const respostas = $input.all();

// Altere para o nome exato do nó que contém os dados dos clientes
const clientes = $("Code in JavaScript2").all();

return respostas.map((item, index) => {
  const resposta = item.json;

  const mensagem =
    resposta.content?.parts?.[0]?.text
    || resposta.text
    || resposta.mensagem
    || "";

  const cliente = clientes[index]?.json || {};

  // Tenta identificar o nome pela saudação do Gemini
  const saudacao = mensagem.match(/Olá,\s*([^!\n]+)!/i);
  const nome = cliente.nome || (saudacao ? saudacao[1].trim() : "");

  return {
    json: {
      numero: index + 1,
      nome,
      email: cliente.email || "",
      mensagem
    }
  };
});
